
MAP
    NAME "nrw_tfis"
    EXTENT 280375 5573233 531799 5824657
    SIZE 600 600
    IMAGECOLOR 255 255 255
    IMAGETYPE png
    SYMBOLSET "/etc/mapserver/symbols.map"
    FONTSET "fonts/fonts.list"
    
    PROJECTION
        'epsg:25832'
    END

    OUTPUTFORMAT
        NAME png
        DRIVER "GD/PNG"
        MIMETYPE "image/png"
        IMAGEMODE PC256
        EXTENSION "png"
        TRANSPARENT ON
    END

    LEGEND
        STATUS ON
        IMAGECOLOR 238 238 238
        KEYSIZE 80 20
        KEYSPACING 5 5
        LABEL
            TYPE TRUETYPE
            FORCE TRUE
            FONT arial
            SIZE 8
            COLOR 0 0 89
        END
    END
    
    DEBUG ON
    WEB
        IMAGEPATH "/tmp/"
        IMAGEURL "/tmp/"
        METADATA
            "WMS_TITLE"                       "Touristik- und Freizeitinformationen NRW (TFIS NRW)"
            "WMS_ABSTRACT"                    "WMS_NW_TFIS"
            "wms_extent"                      "280375 5573233 531799 5824657"
            'wms_srs'                         'EPSG:31466 EPSG:31467 EPSG:25832 EPSG:4326 EPSG:4258 EPSG:3857'
            'ows_keywordlist'                 'Investitionsförderung,finanzschwache Kommunen,kommunale Infrastruktur,kommunales Investitionsprogramm,DAKI,KI 3.0,Rheinland-Pfalz'
            'ows_fees'                        'geldleistungsfrei, Datenlizenz Deutschland - Namensnennung - Version 2.0, URL: https://www.govdata.de/dl-de/by-2-0' #Gebühren
            'ows_accessconstraints'           'Datenlizenz Deutschland - Namensnennung - Version 2.0, URL: https://www.govdata.de/dl-de/by-2-0' #Zugriffsbeschränkungen (falls vorhanden)
            "ows_enable_request" "*"
            "wms_feature_info_mime_type" "text/html"
            "isqueryable" "true"
            "WMS_ENCODING" "UTF-8"
            "gui_wms_featureinfoformat" "text/html"
            "gui_wms_exceptionformat" "text/html"
            # "gml_include_items" "all"
        END
    END #WEB

            LAYER
                NAME "wanderwege"
                TYPE LINE
                UNITS METERS
                CLASSITEM "kat"
                CONNECTION "dbname='tfis_nrw' host=pg port=5432 user='postgres' password='postgres'"
                CONNECTIONTYPE POSTGIS
                DATA "wkb_geometry FROM (SELECT ogc_fid, kat, wkb_geometry FROM wanderwege) AS foo USING UNIQUE ogc_fid USING SRID=25832"
                PROCESSING "CLOSE_CONNECTION=DEFER"
                MAXSCALEDENOM 75001
                METADATA
                    "wms_title" "Wanderwege_LINE"
                    "wms_srs" "EPSG:4326 EPSG:4647 EPSG:31466 EPSG:31467 EPSG:31468 EPSG:25832 EPSG:25833"
                    "wms_metadataurl_type" "TC211"
                    "wms_bbox_extended" "true"
                    "wms_enable_request" "*"
                    "wms_format" "image/png"
                    "wms_transparent" "true"
                    "wms_extent" "280375.039 5573233.639 531799.013 5824657.613"
                    "WMS_FEATURE_INFO_MIME_TYPE" "text/html"
                END
                PROJECTION
                    "epsg:25832"
                END
                SIZEUNITS METERS
                STATUS ON
                SYMBOLSCALEDENOM 1000
                
                CLASS
                    NAME "Fernwanderweg"
                    EXPRESSION "Fernwanderweg"
                    STYLE
                        COLOR 245 199 16
                        WIDTH 20
                        MAXWIDTH 60
                        LINECAP butt
                        LINEJOIN miter
                    END
                END
                
                CLASS
                    NAME "Hauptwanderweg"
                    EXPRESSION "Hauptwanderweg"
                    STYLE
                        COLOR 0 158 115
                        WIDTH 20
                        MAXWIDTH 60
                        LINECAP butt
                        LINEJOIN miter
                        PATTERN 10 20 END
                    END
                END
                
                CLASS
                    NAME "Regionaler Wanderweg"
                    EXPRESSION "Regionaler Wanderweg"
                    STYLE
                        COLOR 213 94 0
                        WIDTH 20
                        MAXWIDTH 60
                        LINECAP butt
                        LINEJOIN miter
                        PATTERN 30 35 END
                    END
                END
                
                CLASS
                    NAME "Rundwanderweg"
                    EXPRESSION "Rundwanderweg"
                    STYLE
                        COLOR 86 180 233
                        WIDTH 20
                        MAXWIDTH 60
                        LINECAP butt
                        LINEJOIN miter
                        PATTERN 30 50 END
                    END
                END
                
                CLASS
                    NAME "Themenwanderweg"
                    EXPRESSION "Themenwanderweg"
                    STYLE
                        COLOR 230 159 0
                        WIDTH 20
                        MAXWIDTH 60
                        LINECAP butt
                        LINEJOIN miter
                        PATTERN 70 40 END
                    END
                END
                
                CLASS
                    NAME "Örtlicher Wanderweg"
                    EXPRESSION "Örtlicher Wanderweg"
                    STYLE
                        COLOR 204 121 167
                        WIDTH 20
                        MAXWIDTH 60
                        LINECAP butt
                        LINEJOIN miter
                        PATTERN 20 58 END
                    END
                END
                
            END
            
